import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Logo from "../assets/logos/logo_branca.png";
import OndaTop from "../assets/images/background_onda1.jpg";
import OndaBottom from "../assets/images/background_onda2.jpg";

const Login = () => {
  const [userDN, setUserDN] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const response = await fetch("http://localhost:5000/authenticate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userDN: `${userDN}@nutrihouse.intra`,
          password,
        }),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("username", data.username);
        navigate("/home");
      } else {
        setError(data.message || "Falha na autenticação");
      }
    } catch (err) {
      setError("Erro ao conectar ao servidor");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative flex items-center justify-center min-h-screen bg-[#FAF9F7] overflow-hidden px-4">
      {/* Onda superior esquerda */}
      <img
        src={OndaTop}
        alt="Onda superior"
        className="absolute top-0 left-0 w-auto h-[40%] max-w-[50%] object-contain z-0"
      />

      {/* Onda inferior direita */}
      <img
        src={OndaBottom}
        alt="Onda inferior"
        className="absolute bottom-0 right-0 w-auto h-[40%] max-w-[50%] object-contain z-0"
      />

      {/* Box de login */}
      <div className="relative z-10 flex flex-col items-center w-[380px] bg-gradient-to-b from-[#B95758] to-[#e14d3a] p-8 rounded-2xl shadow-lg text-center">
        <img
          src={Logo}
          alt="Logo NutriHouse"
          className="w-[200px] mb-[-10px]"
        />

        <h2 className="text-white text-2xl font-semibold mt-1">Bem-vindo</h2>
        <p className="text-white text-sm mb-3">Acesse com seu usuário NH:</p>

        <form onSubmit={handleLogin} className="w-full flex flex-col gap-4">
          <div className="text-left">
            <label htmlFor="usuario" className="text-white font-medium block mb-1">
              Usuário
            </label>
            <input
              id="usuario"
              type="text"
              value={userDN}
              onChange={(e) => setUserDN(e.target.value)}
              placeholder="Digite seu usuário"
              className="w-full p-2 rounded-full border-none outline-none focus:ring-2 focus:ring-yellow-300"
              required
            />
          </div>

          <div className="text-left">
            <label htmlFor="senha" className="text-white font-medium block mb-1">
              Senha
            </label>
            <input
              id="senha"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Digite sua senha"
              className="w-full p-2 rounded-full border-none outline-none focus:ring-2 focus:ring-yellow-300"
              required
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="mt-4 py-3 w-48 mx-auto bg-white text-[#0c0b0b] font-bold rounded-full transition-all hover:bg-gray-100 disabled:opacity-70"
          >
            {loading ? "Entrando..." : "Entrar"}
          </button>
        </form>

        <a
          href="#"
          className="text-white text-sm mt-4 hover:underline"
        >
          Esqueceu a senha?
        </a>

        {error && (
          <p className="text-red-200 text-sm mt-3 bg-red-600/20 px-3 py-2 rounded-lg">
            {error}
          </p>
        )}
      </div>
    </div>
  );
};

export default Login;
